# owner: platform
import unittest
from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from datetime import date

ANA = Student("1", "Diaz", "Ana", "A")


def mark(day, status="absent", sid="1"):
    return Mark(sid, date(2026, 9, day), status)


class BuildNoticeTests(unittest.TestCase):
    def test_names_count_and_ordered_dates(self):
        marks = [mark(9), mark(2), mark(4, "present")]
        expected = (
            "Ana Diaz missed 2 days: "
            "2026-09-02, 2026-09-09"
        )
        self.assertEqual(build_notice(ANA, marks), expected)

    def test_single_day(self):
        text = build_notice(ANA, [mark(3)])
        self.assertIn("missed 1 day:", text)

    def test_excused_not_counted(self):
        marks = [mark(3), mark(4, "excused")]
        text = build_notice(ANA, marks)
        self.assertNotIn("2026-09-04", text)

    def test_other_student_rejected(self):
        marks = [mark(3), mark(4, sid="2")]
        with self.assertRaises(ValueError):
            build_notice(ANA, marks)

    def test_no_absences(self):
        with self.assertRaises(ValueError):
            build_notice(ANA, [mark(3, "present")])

    def test_empty_marks(self):
        with self.assertRaises(ValueError):
            build_notice(ANA, [])
